class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for x in nums:
            for y in nums:
                xy = x & y
                if xy == 0:
                    ans += n
                else:
                    for z in nums:
                        if xy & z == 0:
                            ans += 1
        return ans

