class Solution {
public:
    int countTriplets(vector<int>& nums) {
        long long ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int xy = nums[i] & nums[j];
                if (xy == 0) { ans += n; continue; }
                for (int k = 0; k < n; k++)
                    if ((xy & nums[k]) == 0) ans++;
            }
        return (int)ans;
    }
};

