class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        from collections import Counter
        cnt = Counter(nums)
        vals = list(cnt)
        ans = 0
        for a in vals:
            for b in vals:
                p = a & b
                for z in vals:
                    if p & z == 0:
                        ans += cnt[a] * cnt[b] * cnt[z]
        return ans

