class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        FULL = (1 << 16) - 1
        freq = [0] * (1 << 16)
        for a in nums:
            for b in nums:
                freq[a & b] += 1
        for b in range(16):
            bit = 1 << b
            for m in range(1 << 16):
                if m & bit:
                    freq[m] += freq[m ^ bit]
        return sum(freq[(~x) & FULL] for x in nums)

