class Solution {
public:
    int countTriplets(vector<int>& nums) {
        const int FULL = (1 << 16) - 1;
        vector<int> freq(1 << 16, 0);
        for (int a : nums)
            for (int b : nums)
                freq[a & b]++;
        for (int b = 0; b < 16; b++)
            for (int m = 0; m < (1 << 16); m++)
                if (m & (1 << b))
                    freq[m] += freq[m ^ (1 << b)];
        long long ans = 0;
        for (int x : nums) ans += freq[(~x) & FULL];
        return (int) ans;
    }
};

